import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
const [beforePath,afterPath]=process.argv.slice(2);
const before=readFileSync(beforePath,'utf8'),after=readFileSync(afterPath,'utf8');
const ensure=(ok)=>{if(!ok)throw new Error('PUBLIC_PARSER_CHECK_ASSERTION');};
const extract=(source)=>{const lines=source.split('\n').filter(line=>line.startsWith('  const core='));ensure(lines.length===1);const literal=lines[0].slice('  const core='.length,lines[0].indexOf('.exec(')),last=literal.lastIndexOf('/');ensure(literal[0]==='/'&&last>0);return {literal,regex:new RegExp(literal.slice(1,last),literal.slice(last+1))};};
const a=extract(before),b=extract(after);
ensure(a.literal===String.raw`/^Max core file size\s+(\S+)\s+(\S+)\s+bytes$/m`);
ensure(b.literal===String.raw`/^Max core file size\s+(\S+)\s+(\S+)\s+bytes[ \t]*$/m`);
const predicate="  if(core?.[1]!=='0'||core?.[2]!=='0')throw new Error('D2_CORE_LIMIT');";
ensure(before.split('\n').filter(line=>line===predicate).length===1&&after.split('\n').filter(line=>line===predicate).length===1);
ensure(after===before.replace('bytes$/m.exec(readFileSync(`/proc/${nodePid}/limits`','bytes[ \\t]*$/m.exec(readFileSync(`/proc/${nodePid}/limits`'));
const format=(soft,hard,unit='bytes')=>'Max core file size'.padEnd(25)+' '+soft.padEnd(20)+' '+hard.padEnd(20)+' '+unit.padEnd(10)+'\n';
const cases=[
 {name:'kernel-padded-zero',sample:format('0','0'),expected:true},
 {name:'existing-unpadded-zero',sample:'Max core file size 0 0 bytes\n',expected:true},
 {name:'nonzero-soft',sample:format('1','0'),expected:false},
 {name:'nonzero-hard',sample:format('0','1'),expected:false},
 {name:'unlimited-soft',sample:format('unlimited','0'),expected:false},
 {name:'unlimited-hard',sample:format('0','unlimited'),expected:false},
 {name:'malformed-unit',sample:format('0','0','bytez'),expected:false},
 {name:'extra-token',sample:format('0','0').replace('\n','EXTRA\n'),expected:false}
];
const accept=(core)=>!(core?.[1]!=='0'||core?.[2]!=='0');
const rows=cases.map(c=>{const oldMatch=a.regex.exec(c.sample),newMatch=b.regex.exec(c.sample);return {name:c.name,publicSample:c.sample,sampleSha256:createHash('sha256').update(c.sample).digest('hex'),originalMatched:oldMatch!==null,originalAccepted:accept(oldMatch),candidateMatched:newMatch!==null,candidateCaptures:newMatch?[newMatch[1],newMatch[2]]:null,candidateAccepted:accept(newMatch),expectedAccepted:c.expected,passed:accept(newMatch)===c.expected};});
ensure(cases[0].sample.endsWith('bytes     \n'));ensure(rows[0].originalMatched===false&&rows[0].candidateMatched===true&&rows[0].candidateAccepted===true);ensure(rows[1].originalAccepted===true&&rows[1].candidateAccepted===true);ensure(rows.every(row=>row.passed));
console.log(JSON.stringify({scope:'PUBLIC_STRINGS_ONLY_NO_FIXTURE_IMPORT_OR_REAL_PROC',originalRegex:a.literal,candidateRegex:b.literal,originalPredicateByteExact:true,allOtherSourceBytesExact:true,caseCount:rows.length,negativeControlCount:6,passedCount:rows.filter(row=>row.passed).length,rows}));
